3	import { Button } from "@repo/design-system/components/ui/button";
4	import { cn } from "@repo/design-system/lib/utils";
5	import { useCallback, useEffect, useState } from "react";
6	import { REVEALS, VERDICT } from "./reveals";
7	import { type LineKind, REACHED_LINE_INDEX, TRANSCRIPT } from "./transcript";
8	
9	const LINE_MS = 180;
10	
11	const KIND_GLYPH: Record<string, string> = {
12	  message: "›",
13	  respond: "✓",
14	  think: "∴",
15	  tool: "⚙",
16	};
17	
18	function lineClass(kind: LineKind, highlighted: boolean): string {
19	  if (highlighted) {
20	    return "bg-amber-500/15 text-amber-200";
21	  }
22	  if (kind === "respond") {
23	    return "text-emerald-400";
24	  }
25	  return "text-[#8b949e]";
26	}
27	
28	interface Era3ReachProps {
29	  fenced?: boolean;
30	  /** Presenter drives 0–4. Omitted means the button drives it. */
31	  revealed?: number;
32	}
33	
34	export function Era3Reach({ revealed, fenced }: Era3ReachProps) {
35	  const [printed, setPrinted] = useState(0);
36	  const [selfRevealed, setSelfRevealed] = useState(0);
37	  const [selfFenced, setSelfFenced] = useState(false);
38	
39	  const driven = revealed !== undefined;
40	  const shown = revealed ?? selfRevealed;
41	  const showFence = Boolean(fenced ?? selfFenced);
42	  const reachedShown = shown >= REVEALS.length;
43	
44	  const revealAll = useCallback(() => {
45	    setSelfRevealed(REVEALS.length);
46	    setSelfFenced(true);
47	  }, []);
48	
49	  useEffect(() => {
50	    const reduce = window.matchMedia(
51	      "(prefers-reduced-motion: reduce)"
52	    ).matches;
53	    if (reduce) {
54	      setPrinted(TRANSCRIPT.length);
55	      return;
56	    }
57	    const id = setInterval(() => {
58	      setPrinted((n) => {
59	        if (n >= TRANSCRIPT.length) {
60	          clearInterval(id);
61	          return n;
62	        }
63	        return n + 1;
64	      });
65	    }, LINE_MS);
66	    return () => clearInterval(id);
67	  }, []);
68	
69	  return (
70	    <div className="mt-10 rounded-xl border border-foreground/10 p-4 sm:p-6">
71	      <p className="font-medium text-sm">Everything it could reach</p>
72	      <p className="mt-1 max-w-2xl text-muted-foreground text-sm">
73	        One instruction, on a repo where nothing was fenced off.
74	      </p>
75	
76	      <ol className="mt-4 space-y-1 rounded-lg bg-[#0d1117] p-3 font-mono text-xs">
77	        {TRANSCRIPT.slice(0, printed).map((line, i) => (
78	          <li
79	            className={cn(
80	              "flex items-start gap-3 rounded px-2 py-1 transition-colors",
81	              lineClass(line.kind, i === REACHED_LINE_INDEX && reachedShown)
82	            )}
83	            key={line.text}
84	          >
85	            <span
86	              aria-hidden="true"
87	              className="w-4 shrink-0 text-center opacity-70"
88	            >
89	              {KIND_GLYPH[line.kind]}
90	            </span>
91	            <span className="min-w-0 break-all">{line.text}</span>
92	          </li>
93	        ))}
94	      </ol>
95	
96	      {!driven && shown === 0 && (
97	        <Button
98	          className="mt-4"
99	          onClick={revealAll}
100	          size="sm"
101	          type="button"
102	          variant="outline"
103	        >
104	          See what actually happened
105	        </Button>
106	      )}
107	
108	      {shown > 0 && (
109	        <dl className="mt-6 space-y-4">
110	          {REVEALS.slice(0, shown).map((r) => (
111	            <div
112	              className="grid gap-3 border-foreground/10 border-t pt-4 md:grid-cols-2"
113	              key={r.id}
114	            >
115	              <div>
116	                <dt className="font-mono text-[11px] text-muted-foreground uppercase tracking-wide">
117	                  {r.label}
118	                </dt>
119	                <dd className="mt-2 space-y-1 font-mono text-xs">
120	                  {r.evidence.kind === "lines" ? (
121	                    r.evidence.lines.map((l) => (
122	                      <p className="text-foreground/80" key={l}>
123	                        {l}
124	                      </p>
125	                    ))
126	                  ) : (
127	                    <>
128	                      <p className="text-red-500/90">- {r.evidence.removed}</p>
129	                      <p className="text-emerald-500/90">
130	                        + {r.evidence.added}
131	                      </p>
132	                    </>
133	                  )}
134	                </dd>
135	                <p className="mt-2 max-w-md text-foreground/55 text-sm italic">
136	                  {r.line}
137	                </p>
138	              </div>
139	
140	              {showFence ? (
141	                <div className="fade-in animate-in rounded-lg border border-foreground/10 bg-foreground/[0.03] p-3 duration-300">
142	                  <p className="font-mono text-[11px] text-muted-foreground">
143	                    in reach
144	                  </p>
145	                  <p className="mt-1 font-mono text-foreground/70 text-xs">
146	                    {r.inReach}
147	                  </p>
148	                  <p className="mt-3 font-mono text-[11px] text-muted-foreground">
149	                    out of reach
150	                  </p>
151	                  <p className="mt-1 font-mono text-ht-cyan-700 text-xs dark:text-ht-cyan-300">
152	                    {r.outOfReach}
153	                  </p>
154	                </div>
155	              ) : null}
156	            </div>
157	          ))}
158	        </dl>
159	      )}
160	
161	      {showFence ? (
162	        <p className="mt-6 max-w-2xl text-foreground/55 text-sm italic">
163	          {VERDICT}
164	        </p>
165	      ) : null}
166	    </div>
167	  );
168	}

