async () => {
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const label = () => document.querySelector('nav[aria-label="Presentation beats"] span.font-mono')?.textContent;
  const visible = () => Array.from(document.querySelectorAll('main p.font-medium')).map(p => p.textContent);
  const log = [];
  for (let i = 0; i < 11; i++) {
    log.push({ step: i + 1, beat: label(), demos: visible() });
    window.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true }));
    document.body.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true }));
    await sleep(350);
  }
  return log;
}

