      fencePanels: Array.from(document.querySelectorAll('p')).filter(p => p.textContent === 'out of reach').length,
      verdictShown: Array.from(document.querySelectorAll('p')).some(p => p.textContent.startsWith('Every fence here')),
      truncateAmber: !!document.querySelector('li.bg-amber-500\\/15'),
      harnessShown: Array.from(document.querySelectorAll('*')).some(e => e.textContent === 'Run audit'),
    });
    window.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true }));
    await sleep(300);
  }
  return log;
}

async () => {
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const key = (k) => window.dispatchEvent(new KeyboardEvent('keydown', { key: k, bubbles: true }));
  const label = () => document.querySelector('nav[aria-label="Presentation beats"] span.font-mono')?.textContent;
  const state = () => ({
    beat: label(),
    chatgptTab: document.body.textContent.includes('chat.openai.com'),
    dockedChat: document.body.textContent.includes('This is the Cursor moment'),
    numeralsNotTicks: document.querySelectorAll('nav[aria-label="Presentation beats"] button.size-7').length,
  });
  const log = [{ at: 'beat 1', ...state() }];
  key('ArrowRight'); await sleep(300);
  log.push({ at: 'beat 2', ...state() });
  key('ArrowLeft'); await sleep(300);
  log.push({ at: 'back to beat 1 (must NOT remove demo)', ...state() });
  return log;
}

